BEGIN;

CREATE TABLE IF NOT EXISTS pokemon (
    id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    pokedex_number  INTEGER NOT NULL UNIQUE CHECK (pokedex_number > 0),
    name            VARCHAR(80) NOT NULL UNIQUE,
    type_1          VARCHAR(20) NOT NULL,
    type_2          VARCHAR(20),
    rarity          VARCHAR(20) NOT NULL CHECK (
        rarity IN ('Common', 'Uncommon', 'Rare', 'Epic', 'Legendary', 'Mythical')
    ),
    strength        SMALLINT NOT NULL CHECK (strength BETWEEN 1 AND 100),
    hp              SMALLINT NOT NULL CHECK (hp BETWEEN 1 AND 255),
    attack          SMALLINT NOT NULL CHECK (attack BETWEEN 1 AND 255),
    defense         SMALLINT NOT NULL CHECK (defense BETWEEN 1 AND 255),
    special_attack  SMALLINT NOT NULL CHECK (special_attack BETWEEN 1 AND 255),
    special_defense SMALLINT NOT NULL CHECK (special_defense BETWEEN 1 AND 255),
    speed           SMALLINT NOT NULL CHECK (speed BETWEEN 1 AND 255),
    height_m        NUMERIC(4, 2) CHECK (height_m > 0),
    weight_kg       NUMERIC(6, 2) CHECK (weight_kg > 0),
    generation      SMALLINT NOT NULL CHECK (generation BETWEEN 1 AND 9),
    is_legendary    BOOLEAN NOT NULL DEFAULT FALSE,
    is_mythical     BOOLEAN NOT NULL DEFAULT FALSE,
    abilities       TEXT[] NOT NULL DEFAULT '{}',
    strengths       TEXT[] NOT NULL DEFAULT '{}',
    weaknesses      TEXT[] NOT NULL DEFAULT '{}',
    description     TEXT NOT NULL DEFAULT '',
    created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CHECK (type_2 IS NULL OR type_2 <> type_1),
    CHECK (NOT (is_legendary AND is_mythical))
);

CREATE INDEX IF NOT EXISTS idx_pokemon_name ON pokemon (LOWER(name));
CREATE INDEX IF NOT EXISTS idx_pokemon_rarity ON pokemon (rarity);
CREATE INDEX IF NOT EXISTS idx_pokemon_type_1 ON pokemon (type_1);
CREATE INDEX IF NOT EXISTS idx_pokemon_strength ON pokemon (strength);

